package com.aegisdispatch.controller;
import com.aegisdispatch.model.Ambulance; import com.aegisdispatch.repository.AmbulanceRepository; import com.aegisdispatch.websocket.LiveSocketHandler; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/ambulances")  public class LocationController { private final AmbulanceRepository repo; private final LiveSocketHandler ws; public LocationController(AmbulanceRepository r,LiveSocketHandler w){repo=r;ws=w;} @PostMapping("/{id}/location") public Ambulance update(@PathVariable UUID id,@RequestBody Map<String,Double> p){Ambulance a=repo.findById(id).orElseThrow();a.setLatitude(p.get("latitude"));a.setLongitude(p.get("longitude"));a.setSpeed(p.getOrDefault("speed",0d));a.setHeading(p.getOrDefault("heading",0d));a.setLastLocationAt(Instant.now());Ambulance s=repo.save(a);ws.broadcast("{\"event\":\"LOCATION_UPDATED\",\"ambulanceId\":\""+id+"\",\"latitude\":"+a.getLatitude()+",\"longitude\":"+a.getLongitude()+"}");return s;}}
